<?php
declare(strict_types=1);
require dirname(__DIR__).'/src/bootstrap.php';
use Asyura\Auth;use Asyura\Security;
Auth::requireLogin($config['app_url']);Security::headers();$id=(int)($_GET['id']??0);$stmt=$db->prepare('SELECT * FROM exports WHERE id=?');$stmt->execute([$id]);$export=$stmt->fetch();if(!$export){http_response_code(404);exit('Archive not found');}$path=ASYURA_ROOT.'/storage/exports/'.basename($export['file_name']);if(!is_file($path)){http_response_code(404);exit('Archive file not found');}if(isset($_GET['download'])){header('Content-Type: application/zip');header('Content-Disposition: attachment; filename="'.basename($export['file_name']).'"');header('Content-Length: '.filesize($path));readfile($path);exit;}
$preview=[];$zip=new ZipArchive();if($zip->open($path)===true){for($i=0;$i<$zip->numFiles;$i++){$name=$zip->getNameIndex($i);if(str_ends_with($name,'.csv')){$content=$zip->getFromIndex($i);$lines=array_slice(preg_split('/\r\n|\r|\n/',$content?:''),0,21);$preview[$name]=$lines;}}$zip->close();}
?><!doctype html><html lang="ja"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>アーカイブ閲覧 ‹ 阿修羅</title><link rel="stylesheet" href="<?=e(app_url('assets/admin.css'))?>"></head><body><main class="content" style="margin-left:0"><h1 class="page-title"><?=e($export['export_year'])?>年 アーカイブ</h1><p><a class="button primary" href="?id=<?=$id?>&download=1">ZIPをダウンロード</a> <a class="button" href="<?=e(app_url('admin/?page=data'))?>">戻る</a></p><?php foreach($preview as $name=>$lines):?><div class="panel"><h2><?=e($name)?>（先頭20行）</h2><div class="panel-body"><pre class="codebox"><?=e(implode("\n",$lines))?></pre></div></div><?php endforeach?></main></body></html>
